mapper.select:
SELECT TNA.PLANID,TNA.PLANCODE,TNA.PLANNAME,TNA.PALNYEAR,TNA.PLANTYPE,TNA.PALNCOST,TNA.STARTTIME,TNA.ENDTIME,TNA.REMARKS, TNA.CREATETIME,TNA.STATUS,TNA.OPINIONSTATUS,TNA.ISAUDITOR,PRINCIPAL.STAFFID AS PRISTAFFID,PRINCIPAL.REALNAME AS PRIREALNAME, LEADER.STAFFID LEASTAFFID,LEADER.REALNAME LEAREALNAME,AUDITORG.ORGID AUDORGID,AUDITORG.ORGNAME AUDORGNAME, CRESTAFF.STAFFID CRESTAFFID,CRESTAFF.REALNAME CREREALNAME FROM TBL_NBSJ_AUDITPLAN TNA LEFT JOIN TBL_STAFF PRINCIPAL ON PRINCIPAL.STAFFID = TNA.PRINCIPALID LEFT JOIN TBL_STAFF LEADER ON LEADER.STAFFID = TNA.LEADERID LEFT JOIN TBL_ORGANIZATION AUDITORG ON AUDITORG.ORGID = TNA.AUDITORGID LEFT JOIN TBL_STAFF CRESTAFF ON CRESTAFF.STAFFID = TNA.CREATESTAFFID
and TNA.AUDITORGID = = #{orgId}
AND AND TNA.PRINCIPALID = #{re.principalid}
AND TNA.PLANCODE LIKE concat(concat('%',#{re.plancode}),'%')
and TNA.PLANNAME like concat(concat('%',#{re.planname}),'%')
and TNA.PALNYEAR like concat(concat('%',#{re.palnyear}),'%')
AND TNA.STARTTIME >= #{planStartDate}
AND TNA.ENDTIME <= #{planEndDate}
ORDER BY TNA.PLANID DESC
